INSERT INTO test_paper(name,description,mode,total_score,pass_score,duration_minutes,status,created_by) SELECT '质量意识与异常问题闭环考核试卷','理解标准作业、记录追溯、异常反馈和改进验证的基本要求，形成持续改进意识。','FIXED',100,60,30,'PUBLISHED',@demo_owner WHERE NOT EXISTS (SELECT 1 FROM test_paper WHERE name='质量意识与异常问题闭环考核试卷' AND created_by=@demo_owner);
INSERT INTO test_paper_question(paper_id,question_id,score,sort_no) SELECT @demo_paper,q.id,20,q.sort_no FROM question_item q WHERE q.bank_id=@demo_bank AND q.source LIKE '企业培训演示初始化/v1/quality/q%' AND NOT EXISTS (SELECT 1 FROM test_paper_question pq WHERE pq.paper_id=@demo_paper AND pq.question_id=q.id);
INSERT INTO assessment_task(name,paper_id,start_at,end_at,duration_minutes,candidate_scope,status,allow_retake,max_attempts,shuffle_questions,shuffle_options,show_result_immediately,created_by) SELECT '质量意识与异常问题闭环考核',@demo_paper,DATE_SUB(NOW(3),INTERVAL 1 DAY),DATE_ADD(NOW(3),INTERVAL 30 DAY),30,'ALL','STARTED',TRUE,2,TRUE,FALSE,TRUE,@demo_owner WHERE NOT EXISTS (SELECT 1 FROM assessment_task WHERE name='质量意识与异常问题闭环考核' AND created_by=@demo_owner);
INSERT INTO training(name,description,survey_enabled,questions_json,created_by,assessment_id) SELECT '质量意识与异常问题闭环培训','理解标准作业、记录追溯、异常反馈和改进验证的基本要求，形成持续改进意识。',TRUE,'[{"id": "demo-quality-rating", "type": "RATING", "title": "您对本次培训的整体满意度如何？", "required": true, "options": []}, {"id": "demo-quality-single", "type": "SINGLE", "title": "本次培训内容对岗位工作的帮助程度如何？", "required": true, "options": ["帮助很大", "有一定帮助", "帮助较少"]}, {"id": "demo-quality-text", "type": "TEXT", "title": "您希望后续培训补充哪些内容？", "required": false, "options": []}]',@demo_owner,@demo_exam WHERE NOT EXISTS (SELECT 1 FROM training WHERE name='质量意识与异常问题闭环培训' AND created_by=@demo_owner);
